/**
 * src/pages/scan/Phase4Results.jsx
 *
 * Final phase of the Advanced Scan pipeline — Risk Report.
 * Aggregates Phase 1–3 context data into a single exportable report.
 * Uses data already generated by the backend during Phase 3.
 */
import { useEffect } from "react";
import { useNavigate }          from "react-router-dom";
import AppLayout                from "../../components/layout/AppLayout";
import ScanStepper              from "../../components/layout/ScanStepper";
import ExportPanel              from "../../components/scan/ExportPanel";
import RiskBadge                from "../../components/scan/RiskBadge";
import { useScan }              from "../../context/ScanContext";
const SEV_COLOR = {
  Critical: "#ff4d4d",
  High:     "#f97316",
  Medium:   "#f59e0b",
  Low:      "#22c55e",
  Info:     "#60a5fa",
};

// Aggregate risk counts from phase3AuditResults
function buildRiskCounts(auditResults = []) {
  const counts = { Critical: 0, High: 0, Medium: 0, Low: 0, Info: 0 };
  auditResults.forEach(h => {
    (h.cves || []).forEach(cve => {
      const sev = cve.severity || "Info";
      counts[sev] = (counts[sev] || 0) + 1;
    });
  });
  return counts;
}

export default function Phase4Results() {
  const navigate = useNavigate();
  const {
    scanId, target,
    phase1Summary,
    phase2Summary,
    phase3Summary,
    phase3AuditResults,   // ← set by Phase3Results after audit
    saveStatus,
    resetScan,
  } = useScan();

  // Redirect guard — if no audit results exist, user navigated here directly
  useEffect(() => {
    if (!phase3AuditResults?.length && !phase3Summary) {
      navigate("/scan/advanced-scan", { replace: true });
    }
  }, [phase3AuditResults, phase3Summary, navigate]);

  if (!phase3AuditResults?.length && !phase3Summary) return null;

  const riskCounts   = buildRiskCounts(phase3AuditResults);
  const activeHosts  = (phase3AuditResults || []).filter(h => h.is_active);
  const totalCVEs    = Object.values(riskCounts).reduce((a, b) => a + b, 0);

  const overallRiskLevel =
    riskCounts.Critical > 0 ? "Critical" :
    riskCounts.High     > 0 ? "High"     :
    riskCounts.Medium   > 0 ? "Medium"   :
    riskCounts.Low      > 0 ? "Low"      : "Info";

  const overallRiskScore = phase3Summary
    ? Math.round(
        (riskCounts.Critical * 40 + riskCounts.High * 20 + riskCounts.Medium * 10 + riskCounts.Low * 2) /
        Math.max(activeHosts.length, 1)
      )
    : 0;

  return (
    <AppLayout pageTitle="Risk Report" saveStatus={saveStatus}>
      <ScanStepper current={4} />

      <div className="page-inner">

        {/* Header */}
        <div className="page-title-row">
          <div>
            <h2 className="page-title">Risk Report</h2>
            <p className="page-subtitle">
              Full pipeline complete · Target: <code className="ip-code">{target}</code>
              {scanId && <span className="muted"> · Scan #{scanId}</span>}
            </p>
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button className="btn btn--ghost" onClick={() => navigate("/scan/advanced-scan")}>← Back</button>
          </div>
        </div>

        {/* ── Overall Risk Score ───────────────────────────────────────── */}
        <div style={{
          display: "flex", gap: 16, flexWrap: "wrap", marginBottom: 24,
          padding: "20px 24px", background: "var(--bg-white)",
          border: "1px solid var(--border)", borderRadius: 10,
          borderLeft: `4px solid ${SEV_COLOR[overallRiskLevel] || "#60a5fa"}`,
        }}>
          <div style={{ flex: 1, minWidth: 180 }}>
            <p style={{ fontSize: "0.75rem", fontWeight: 600, color: "var(--text-muted)", marginBottom: 6 }}>
              OVERALL RISK LEVEL
            </p>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <RiskBadge level={overallRiskLevel} score={Math.min(overallRiskScore, 100)} />
            </div>
          </div>
          <div style={{ display: "flex", gap: 24, flexWrap: "wrap", alignItems: "center" }}>
            {Object.entries(riskCounts).map(([sev, count]) => (
              count > 0 && (
                <div key={sev} style={{ textAlign: "center" }}>
                  <div style={{ fontSize: "1.4rem", fontWeight: 700, color: SEV_COLOR[sev], fontFamily: "var(--mono)" }}>
                    {count}
                  </div>
                  <div style={{ fontSize: "0.7rem", color: "var(--text-muted)", fontWeight: 600 }}>{sev}</div>
                </div>
              )
            ))}
          </div>
        </div>

        {/* ── Pipeline Summary ─────────────────────────────────────────── */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12, marginBottom: 24 }}>
          {[
            { label: "Hosts Discovered",  value: phase1Summary?.total_hosts    ?? "—", icon: "①", ok: true },
            { label: "Active Hosts",       value: phase1Summary?.active_hosts   ?? "—", icon: "🟢" },
            { label: "Hosts with Ports",   value: phase2Summary?.hosts_with_ports ?? "—", icon: "②" },
            { label: "Hosts Audited",      value: phase3Summary?.total_hosts    ?? "—", icon: "③" },
            { label: "Critical Hosts",     value: phase3Summary?.critical_hosts ?? "—", icon: "🔴", danger: (phase3Summary?.critical_hosts ?? 0) > 0 },
            { label: "Total CVEs Found",   value: totalCVEs,                              icon: "⚠", danger: totalCVEs > 0 },
          ].map(({ label, value, icon, danger }) => (
            <div key={label} style={{
              padding: "14px 16px",
              background: "var(--bg-white)",
              border: "1px solid var(--border)",
              borderRadius: 8,
            }}>
              <div style={{ fontSize: "0.72rem", fontWeight: 600, color: "var(--text-muted)", marginBottom: 6 }}>
                {icon} {label}
              </div>
              <div style={{
                fontSize: "1.6rem", fontWeight: 700, fontFamily: "var(--mono)",
                color: danger ? SEV_COLOR.Critical : "var(--text-dark)",
              }}>
                {value}
              </div>
            </div>
          ))}
        </div>

        {/* ── Host Risk Table ──────────────────────────────────────────── */}
        {activeHosts.length > 0 && (
          <div style={{ marginBottom: 24 }}>
            <h3 style={{ fontSize: "0.88rem", fontWeight: 700, color: "var(--text-mid)", marginBottom: 12 }}>
              Host Risk Breakdown
            </h3>
            <div className="results-table-wrap">
              <table className="results-table">
                <thead>
                  <tr>
                    <th>IP Address</th>
                    <th>Hostname</th>
                    <th>Risk Level</th>
                    <th>Risk Score</th>
                    <th>Open Ports</th>
                    <th>CVEs</th>
                    <th>OS</th>
                  </tr>
                </thead>
                <tbody>
                  {activeHosts
                    .slice()
                    .sort((a, b) => (b.host_risk_score || 0) - (a.host_risk_score || 0))
                    .map(h => (
                      <tr key={h.ip_address}>
                        <td><code className="ip-code">{h.ip_address}</code></td>
                        <td>{h.hostname || <span className="muted">—</span>}</td>
                        <td>
                          <span style={{
                            color: SEV_COLOR[h.host_risk_level] || "#60a5fa",
                            fontWeight: 700, fontSize: 12,
                          }}>
                            {h.host_risk_level || "Info"}
                          </span>
                        </td>
                        <td>
                          <span style={{ fontFamily: "var(--mono)", fontSize: 12 }}>
                            {h.host_risk_score ?? 0}/100
                          </span>
                        </td>
                        <td>{h.open_ports?.length ?? 0}</td>
                        <td>
                          <span style={{ color: (h.cves?.length ?? 0) > 0 ? SEV_COLOR.High : "var(--text-faint)", fontFamily: "var(--mono)", fontSize: 12 }}>
                            {h.cves?.length ?? 0}
                          </span>
                        </td>
                        <td style={{ fontSize: 12, color: "var(--text-muted)" }}>{h.os_guess || "—"}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* ── Export ──────────────────────────────────────────────────── */}
        <ExportPanel
          results={phase3AuditResults || []}
          summary={phase3Summary}
          scanId={scanId}
          target={target}
        />

        {/* ── Footer ──────────────────────────────────────────────────── */}
        <div className="phase-footer" style={{ marginTop: 16 }}>
          <span className="muted" style={{ fontSize: 13 }}>
            ✓ Advanced Scan pipeline complete — all 4 phases finished.
          </span>
          <div style={{ display: "flex", gap: 10 }}>
            <button className="btn btn--ghost" onClick={() => navigate("/history")}>
              View History
            </button>
            <button className="btn btn--primary" onClick={() => { resetScan(); navigate("/dashboard"); }}>
              ↺ New Scan
            </button>
          </div>
        </div>

      </div>
    </AppLayout>
  );
}
